script:
card({ name: "Dice roll", icon: 'dice', permissions: ['sound'] });
const words = {
  roll: "Roll",
  tap: "Tap Roll to throw the dice",
  rolled: "{p0} rolled {p1}",
};

// ctx.random() gives the same number on every phone.
const faces = ['⚀', '⚁', '⚂', '⚃', '⚄', '⚅'];

function init() {
  return { rolls: [] };
}

on.roll = (state, args, ctx) => {
  const value = Math.floor(ctx.random() * 6) + 1;
  ctx.sound(value === 6 ? 'coin' : 'tick');
  state.rolls = [{ name: ctx.authorName, value }, ...state.rolls].slice(0, 5);
};

function view(state) {
  const last = state.rolls[0];
  return column([
    text(last ? faces[last.value - 1] + ' ' + last.value : '?', { size: 'huge', bold: true, align: 'center', tone: 'accent' }),
    text(last ? words.rolled.replace('{p0}', last.name).replace('{p1}', last.value) : words.tap, { align: 'center' }),
    button(words.roll, 'roll', null, { tone: 'accent', align: 'center' }),
    ...state.rolls.slice(1).map(r => text(r.name + ': ' + r.value, { size: 'small', tone: 'muted', align: 'center' })),
  ]);
}
